import{_ as o,o as r,c as e,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Science Working Group 2020-07-23","description":"","frontmatter":{"title":"Ceph Science Working Group 2020-07-23","date":"2020-07-23T00:00:00.000Z","updated":"2020-07-28T00:00:00.000Z","tags":["Ceph用户组","分布式存储","Ceph集群","故障分析","升级与部署"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Science_Working_Group_2020-07-23.md","filePath":"posts/2020/Ceph_Science_Working_Group_2020-07-23.md","lastUpdated":1780460162000}'),i={name:"posts/2020/Ceph_Science_Working_Group_2020-07-23.md"};function l(n,t,s,h,c,g){return r(),e("div",null,[...t[0]||(t[0]=[a('<h3 id="会议纪要-ceph用户组会议-2020年7月" tabindex="-1">会议纪要：Ceph用户组会议 - 2020年7月 <a class="header-anchor" href="#会议纪要-ceph用户组会议-2020年7月" aria-label="Permalink to &quot;会议纪要：Ceph用户组会议 - 2020年7月&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><ul><li><strong>日期</strong>：2020年7月</li><li><strong>形式</strong>：虚拟会议</li><li><strong>目的</strong>：为科学研究和大型集群领域的专业人士提供一个非正式的交流平台，每两个月举行一次。</li><li><strong>参与者</strong>：来自相关领域的专业人士和研究人员。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><strong>近期故障和问题分享</strong><ul><li><strong>部分集群故障</strong>：1604到1804版本中，<code>ifupdown</code>脚本中的竞态条件导致绑定接口在VLAN中无法启动默认路由，影响OSD与客户端的通信。</li><li><strong>解决方案</strong>：使用更新版本的<code>ifupdown</code>包，并在systemd服务文件中添加覆盖，确保OSD在无法ping通内部基础设施时不会启动。</li><li><strong>集群容量管理</strong>：13PB生产集群满容量，平衡器问题导致重新平衡无效。</li><li><strong>应对措施</strong>：停止集群三天，添加新硬件，使用<code>app-map remap</code>工具重新分配PG，并优先处理满载的OSD。</li><li><strong>Ceph Octopus升级经验</strong>：从Nautilus升级到Octopus 15.2.3，遇到性能下降和RGW统计问题。</li><li><strong>问题</strong>：RGW统计数据不准确，导致用户配额问题；RGW日志记录问题导致性能问题。</li><li><strong>解决方案</strong>：暂时回滚到Nautilus，调整日志级别。</li><li><strong>Ceph Orchestrator和容器化部署</strong>：讨论使用Ceph Orchestrator进行容器化部署的挑战和经验。</li><li><strong>展望</strong>：容器化部署是未来趋势，但目前存在一些技术障碍。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>未来会议安排</strong>：下一次会议预计在9月的第四或第五个星期三举行。</li><li><strong>信息共享</strong>：鼓励参与者通过会议链接中的pad共享信息和问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>技术问题跟进</strong>：继续关注和解决Ceph Octopus升级后的性能和稳定性问题。</li><li><strong>容器化部署测试</strong>：进一步测试和优化Ceph Orchestrator的容器化部署方案。</li><li><strong>社区支持</strong>：通过邮件列表和私人通讯渠道，加强社区成员之间的沟通和支持。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li><strong>Ceph Octopus的新特性</strong>：如实时镜像迁移等，尚未有实际应用经验分享。</li><li><strong>Ceph社区动态</strong>：提及CERN的LZ4压缩问题技术讨论，鼓励参与者观看相关视频。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li><strong>感谢参与者</strong>：会议在积极的氛围中结束，期待下一次会议的交流。</li></ul>',13)])])}const d=o(i,[["render",l]]);export{u as __pageData,d as default};
